"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["11570"],{65212(e){e.exports=JSON.parse('{"id":"V4-069","slug":"form-10-k","term":"Form 10-K","also_known_as":[],"difficulty":"Intermediate","definition":"A Form 10-K is the detailed annual report that most public companies in the United States must file with the Securities and Exchange Commission, describing their business, risks, financial performance and audited financial statements.","explanation":["The 10-K is more comprehensive than the glossy annual report many companies send to shareholders. It follows a standard structure set by the Securities and Exchange Commission.","Key sections include a description of the business; risk factors; legal proceedings; management\u2019s discussion and analysis of financial condition and results; the audited financial statements and notes; information on internal controls; and details on executive pay and governance, often included by reference to the proxy statement.","For example, an investor researching a company might read the risk factors section of its 10-K to understand threats such as dependence on key customers, regulatory changes or competition.","Deadlines for filing depend on company size, ranging from 60 to 90 days after the end of the financial year. Companies also file quarterly reports on Form 10-Q and current reports on Form 8-K for significant events. Foreign companies listed in the United States file a similar annual report on Form 20-F. All filings are freely available through the SEC\u2019s online database, EDGAR."],"note":"","total":1725,"prev":{"slug":"foreign-exchange","term":"Foreign Exchange (Forex)"},"next":{"slug":"forward-contract","term":"Forward Contract"}}')}}]);